class Solution {
    public String treeNodeRelationship(int n, int[][] edges, int nodeA, int nodeB) {
        java.util.List<java.util.List<Integer>> g = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new java.util.ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] par = new int[n], dep = new int[n];
        java.util.Arrays.fill(par, -1);
        boolean[] vis = new boolean[n]; vis[0] = true;
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        q.offer(0);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (!vis[v]) { vis[v] = true; par[v] = u; dep[v] = dep[u] + 1; q.offer(v); }
        }
        if (dep[nodeA] != dep[nodeB]) return "others";
        return par[nodeA] == par[nodeB] ? "siblings" : "cousins";
    }
}

class Solution {
public:
    string treeNodeRelationship(int n, vector<vector<int>>& edges, int nodeA, int nodeB) {
        vector<vector<int>> g(n);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<int> par(n, -1), dep(n, 0);
        vector<bool> vis(n, false); vis[0] = true;
        queue<int> q; q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : g[u]) if (!vis[v]) { vis[v] = true; par[v] = u; dep[v] = dep[u] + 1; q.push(v); }
        }
        if (dep[nodeA] != dep[nodeB]) return "others";
        return par[nodeA] == par[nodeB] ? "siblings" : "cousins";
    }
};
